{
  "nxCloudUrl": "https://cloud.nx.app",
  "$schema": "./node_modules/nx/schemas/nx-schema.json",
  "pluginsConfig": {
    "@nx/js": {
      "analyzeSourceFiles": true
    }
  },
  "plugins": [
    {
      "plugin": "@nx/oxlint",
      "options": {
        "targetName": "lint"
      }
    },
    {
      "plugin": "@nx/eslint/plugin",
      "options": {
        "targetName": "lint-templates",
        "extensions": ["ts", "html"]
      }
    },
    {
      "plugin": "@nx/storybook/plugin",
      "options": {
        "buildStorybookTargetName": "build-storybook",
        "serveStorybookTargetName": "storybook",
        "testStorybookTargetName": "test-storybook",
        "staticStorybookTargetName": "static-storybook"
      }
    },
    {
      "plugin": "@nx/playwright/plugin",
      "options": {
        "targetName": "e2e"
      }
    },
    {
      "plugin": "@nx/vite/plugin",
      "options": {
        "buildTargetName": "build",
        "previewTargetName": "preview",
        "serveTargetName": "serve",
        "serveStaticTargetName": "serve-static"
      }
    },
    {
      "plugin": "./tools/nx/typecheck-specs.mjs"
    },
    {
      "plugin": "@nx/vitest",
      "options": {
        "testTargetName": "test"
      }
    }
  ],
  "namedInputs": {
    "default": ["{projectRoot}/**/*", "sharedGlobals"],
    "production": [
      "default",
      "!{projectRoot}/**/*.spec.[jt]s",
      "!{projectRoot}/tsconfig.*spec.json",
      "!{projectRoot}/tsconfig.storybook.json",
      "!{projectRoot}/tsconfig.editor.json",
      "!{projectRoot}/karma.conf.js",
      "!{projectRoot}/**/?(*.)+(spec|test).[jt]s?(x)?(.snap)",
      "!{projectRoot}/jest.config.[jt]s",
      "!{projectRoot}/.storybook/**/*",
      "!{projectRoot}/**/*.stories.@(js|jsx|ts|tsx|mdx)",
      "!{projectRoot}/src/*test-setup.[jt]s",
      "!{projectRoot}/playwright.config.[jt]s",
      "!{projectRoot}/vitest.config.*",
      "!{projectRoot}/gpu-crosscheck/**/*",
      "!{projectRoot}/.oxlintrc.json",
      "!{projectRoot}/eslint.config.mjs",
      "!{projectRoot}/tsconfig.spec.json"
    ],
    "sharedGlobals": [],
    "federation": ["{workspaceRoot}/tools/federation/workspace-federation.js"],
    "non-cdk-deployed-version": [
      {
        "runtime": "npx tsx ./tools/version-handling/latest-non-cdk-deployed-tag.ts"
      }
    ],
    "cdk-deployed-version": [
      {
        "runtime": "npx tsx ./tools/version-handling/latest-cdk-deployed-tag.ts"
      }
    ]
  },
  "targetDefaults": {
    "nx-release-publish": {
      "dependsOn": ["build"],
      "options": {
        "packageRoot": "{workspaceRoot}/dist/{projectRoot}"
      }
    },
    "deploy": {
      "dependsOn": ["^build"]
    },
    "build": {
      "inputs": ["sharedGlobals", "production", "^production"],
      "dependsOn": ["^build"],
      "outputs": ["{workspaceRoot}/dist/{projectRoot}"],
      "cache": true
    },
    "test": {
      "inputs": [
        "default",
        "^production",
        "{workspaceRoot}/jest.preset.cjs",
        "{workspaceRoot}/jest.config.ts",
        "{workspaceRoot}/.codecov.yml"
      ],
      "outputs": ["{workspaceRoot}/coverage/{projectRoot}"],
      "cache": true,
      "configurations": {
        "ci": {
          "codeCoverage": true
        }
      }
    },
    "test-integration": {
      "inputs": ["default", "^production"],
      "outputs": ["{workspaceRoot}/coverage/{projectRoot}"],
      "cache": true,
      "configurations": {
        "ci": {
          "codeCoverage": true
        }
      }
    },
    "build-storybook": {
      "inputs": [
        "default",
        "^production",
        "{projectRoot}/.storybook/**/*",
        "{projectRoot}/tsconfig.storybook.json"
      ],
      "cache": true
    },
    "@nx/jest:jest": {
      "inputs": [
        "default",
        "^production",
        "{workspaceRoot}/jest.preset.cjs",
        "{workspaceRoot}/jest.config.ts",
        "{workspaceRoot}/.codecov.yml"
      ],
      "outputs": ["{workspaceRoot}/coverage/{projectRoot}"],
